static Vector2 SphereUV(Vector3 n){return new Vector2(Mathf.Atan2(n.z,n.x)/(Mathf.PI*2)+.5f,Mathf.Acos(Mathf.Clamp(n.y,-1,1))/Mathf.PI);}
static void BallTri(G g,Vector3 a,Vector3 b,Vector3 c,Color color,int tile){if(Vector3.Dot(Vector3.Cross(b-a,c-a),(a+b+c))<0){var swap=b;b=c;c=swap;}g.Tri(a,b,c,color,tile,SphereUV(a.normalized),SphereUV(b.normalized),SphereUV(c.normalized));}
static Vector3[] Ico(){float p=(1+Mathf.Sqrt(5))/2;return new[]{new Vector3(-1,p,0),new Vector3(1,p,0),new Vector3(-1,-p,0),new Vector3(1,-p,0),new Vector3(0,-1,p),new Vector3(0,1,p),new Vector3(0,-1,-p),new Vector3(0,1,-p),new Vector3(p,0,-1),new Vector3(p,0,1),new Vector3(-p,0,-1),new Vector3(-p,0,1)}.Select(v=>v.normalized).ToArray();}
static void BallSphere(G g,float radius,int rings,int sides,bool football,bool far=false){var ico=Ico();for(int y=0;y<rings;y++)for(int x=0;x<sides;x++){float a=y*Mathf.PI/rings,b=(y+1)*Mathf.PI/rings,t=x*Mathf.PI*2/sides,u=(x+1)*Mathf.PI*2/sides;Func<float,float,Vector3> P=(lat,lon)=>new Vector3(Mathf.Sin(lat)*Mathf.Cos(lon),Mathf.Cos(lat),Mathf.Sin(lat)*Mathf.Sin(lon))*radius;var aa=P(a,t);var bb=P(a,u);var cc=P(b,u);var dd=P(b,t);Color color=football?(far?(ico.Max(v=>Vector3.Dot(v,(aa+bb+cc+dd).normalized))>.91f?new Color(.025f,.028f,.030f):White):new Color(.035f,.038f,.040f)):new Color(.78f,.285f,.055f);int tile=football?26:27;
// Keep the basketball's UV seam continuous, including the longitude wrap.
if(y>0){if(football)BallTri(g,aa,bb,cc,color,tile);else g.Tri(aa,bb,cc,color,tile,new Vector2(x/(float)sides,y/(float)rings),new Vector2((x+1)/(float)sides,y/(float)rings),new Vector2((x+1)/(float)sides,(y+1)/(float)rings));}
if(y<rings-1){if(football)BallTri(g,aa,cc,dd,color,tile);else g.Tri(aa,cc,dd,color,tile,new Vector2(x/(float)sides,y/(float)rings),new Vector2((x+1)/(float)sides,(y+1)/(float)rings),new Vector2(x/(float)sides,(y+1)/(float)rings));}}}
static void Panel(G g,List<Vector3> points,Color color,float radius){var center=points.Aggregate(Vector3.zero,(sum,p)=>sum+p).normalized;var axis=Vector3.Cross(center,Mathf.Abs(center.y)>.85f?Vector3.forward:Vector3.up).normalized;var other=Vector3.Cross(center,axis);points=points.OrderBy(p=>Mathf.Atan2(Vector3.Dot(p,other),Vector3.Dot(p,axis))).ToList();var curved=new List<Vector3>();for(int i=0;i<points.Count;i++)for(int j=0;j<3;j++)curved.Add(Vector3.Slerp(points[i],points[(i+1)%points.Count],j/3f).normalized);var edge=curved.Select(p=>Vector3.Lerp(p,center,.024f).normalized*radius).ToArray();var inner=edge.Select(p=>Vector3.Lerp(center,p.normalized,.50f).normalized*radius).ToArray();for(int j=0;j<edge.Length;j++){int k=(j+1)%edge.Length;BallTri(g,center*radius,edge[j],edge[k],color,26);}}
static Mesh MakeFootball(bool far){var g=new G();float r=.115f;if(far){BallSphere(g,r,6,12,true,true);}else{BallSphere(g,r*.980f,8,16,true);var v=Ico();float edge=(v[0]-v[1]).sqrMagnitude;Func<int,int,bool> adjacent=(a,b)=>a!=b&&Mathf.Abs((v[a]-v[b]).sqrMagnitude-edge)<.0001f;for(int i=0;i<12;i++){int vertex=i;var neighbors=Enumerable.Range(0,12).Where(j=>adjacent(vertex,j)).ToArray();Panel(g,neighbors.Select(j=>(v[vertex]*2+v[j]).normalized).ToList(),new Color(.025f,.028f,.030f),r);}
int faces=0;for(int a=0;a<12;a++)for(int b=a+1;b<12;b++)for(int c=b+1;c<12;c++)if(adjacent(a,b)&&adjacent(b,c)&&adjacent(c,a)){Panel(g,new[]{(v[a]*2+v[b]).normalized,(v[b]*2+v[a]).normalized,(v[b]*2+v[c]).normalized,(v[c]*2+v[b]).normalized,(v[c]*2+v[a]).normalized,(v[a]*2+v[c]).normalized}.ToList(),new Color(.91f,.915f,.89f),r);faces++;}if(faces!=20)throw new Exception("Football truncated icosahedron construction failed");}
var mesh=g.Save(far?"Football centered far":"Football centered 32 panel near");mesh.normals=mesh.vertices.Select(p=>p.normalized).ToArray();EditorUtility.SetDirty(mesh);return mesh;}
static Mesh MakeBasketball(bool far){var g=new G();BallSphere(g,.122f,far?6:16,far?12:32,false,far);var mesh=g.Save(far?"Basketball centered far":"Basketball centered leather near");mesh.normals=mesh.vertices.Select(p=>p.normalized).ToArray();EditorUtility.SetDirty(mesh);return mesh;}
static GameObject BallPrefab(string name,Mesh near,Mesh far,float radius){var go=new GameObject(name);var renders=new List<Renderer>();foreach(var pair in new[]{new[]{near},new[]{far}}){var child=new GameObject(renders.Count==0?"Near detailed ball":"Far lightweight ball");child.transform.SetParent(go.transform,false);child.AddComponent<MeshFilter>().sharedMesh=pair[0];var r=child.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;renders.Add(r);}var collider=go.AddComponent<SphereCollider>();collider.center=Vector3.zero;collider.radius=radius;var lod=go.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.06f,new[]{renders[0]}),new LOD(.004f,new[]{renders[1]})});lod.RecalculateBounds();var prefab=PrefabUtility.SaveAsPrefabAsset(go,D+name+".prefab");UnityEngine.Object.DestroyImmediate(go);return prefab;}
static void BuildQualityBallPrefabs(){footballPrefab=BallPrefab("Football - Centered",MakeFootball(false),MakeFootball(true),.115f);basketballPrefab=BallPrefab("Basketball - Centered",MakeBasketball(false),MakeBasketball(true),.122f);}
static void PlaceBall(GameObject prefab,string name,Vector3 position,Vector3 angles){var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root.transform);go.name=name;go.transform.localPosition=position;go.transform.localRotation=Quaternion.Euler(angles);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);}
static void Rack(Vector3 center,float width){foreach(float x in new[]{-width/2,width/2}){structure.Pole(center+new Vector3(x,.02f,-.28f),center+new Vector3(x,1.1f,-.28f),.035f,Black);structure.Pole(center+new Vector3(x,.02f,.28f),center+new Vector3(x,1.1f,.28f),.035f,Black);structure.Pole(center+new Vector3(x,.03f,-.35f),center+new Vector3(x,.03f,.35f),.045f,Black);}foreach(float y in new[]{.49f,.89f})foreach(float z in new[]{-.11f,.11f})structure.Pole(center+new Vector3(-width/2,y,z),center+new Vector3(width/2,y,z),.022f,Black);}
static void Spot(G g,Vector3 center,float radius){for(int i=0;i<20;i++){float a=i*Mathf.PI/10,b=(i+1)*Mathf.PI/10;g.Tri(center,center+new Vector3(Mathf.Cos(b),0,Mathf.Sin(b))*radius,center+new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*radius,White);}}
